INSERT INTO programs (id, data) VALUES ('aviation', '{"id": "aviation", "coverPhoto": "data:image/jpeg;base64,", "title": "National Aviation Museum", "date": "Aug 30", "dateReached": false, "location": "Seoul", "locationKo": "서울", "level": "A1", "category": "science", "isMuseum": true, "theme": "Discover how airplanes fly and meet the people who make aviation possible.", "themeKo": "비행기가 어떻게 하늘을 나는지 배우고, 항공 산업을 이끄는 사람들을 만나보았어요.", "emoji": "✈️", "icon": "plane", "roster": ["ella", "noah", "mia"], "vocabulary": [{"id": "airplane", "en": "airplane", "meaning": "A machine that flies in the sky.", "emoji": "✈️"}, {"id": "pilot", "en": "pilot", "meaning": "The person who flies the plane.", "emoji": "🧑‍✈️"}, {"id": "airport", "en": "airport", "meaning": "A place where planes take off and land.", "emoji": "🛫"}, {"id": "runway", "en": "runway", "meaning": "The long road a plane uses to take off.", "emoji": "🛣️"}, {"id": "engine", "en": "engine", "meaning": "The part that gives the plane power.", "emoji": "⚙️"}, {"id": "flight", "en": "flight", "meaning": "A trip made by an airplane.", "emoji": "🧳"}], "bigQuestion": "How can an airplane fly?", "bigQuestionOptions": ["Its wings lift it up", "The engine pushes it fast", "I''m not sure yet"], "challenge": [{"id": "q1", "type": "mc", "prompt": "What do we call the person who flies a plane?", "options": ["Pilot", "Driver", "Captain of a ship"], "answer": 0}, {"id": "q2", "type": "tf", "prompt": "A runway is used for take off and landing.", "answer": true}, {"id": "q3", "type": "mc", "prompt": "Which part gives the plane power?", "options": ["Wing", "Engine", "Window"], "answer": 1}, {"id": "q4", "type": "match", "prompt": "Match each word to its picture!", "pairs": [{"key": "airplane", "word": "airplane", "emoji": "✈️"}, {"key": "pilot", "word": "pilot", "emoji": "🧑‍✈️"}, {"key": "engine", "word": "engine", "emoji": "⚙️"}]}], "missions": [{"id": "m1", "text": "Find the oldest airplane."}, {"id": "m2", "text": "Find something a pilot uses."}, {"id": "m3", "text": "Find an airplane engine."}, {"id": "m4", "text": "Take a photo of your favorite exhibit.", "isPhoto": true}], "remember": [{"id": "r1", "type": "mc", "prompt": "What flies in the sky?", "options": ["A boat", "An airplane", "A train"], "answer": 1}, {"id": "r2", "type": "tf", "prompt": "A pilot flies the airplane.", "answer": true}, {"id": "r3", "type": "mc", "prompt": "Where do planes take off?", "options": ["Runway", "Kitchen", "Playground"], "answer": 0}]}');
INSERT INTO programs (id, data) VALUES ('seodaemun', '{"id": "seodaemun", "coverPhoto": "data:image/jpeg;base64,", "title": "Seodaemun Museum of Natural History", "date": "Sep 6", "dateReached": false, "location": "Seoul", "locationKo": "서울", "level": "Pre-A1", "category": "nature", "isMuseum": true, "theme": "Step back in time and meet creatures that once ruled the earth.", "themeKo": "먼 옛날로 돌아가 지구를 지배했던 생물들을 만나보는 시간이었어요.", "emoji": "🦴", "icon": "nature", "roster": ["ella", "noah"], "vocabulary": [{"id": "dinosaur", "en": "dinosaur", "meaning": "A very big animal that lived long ago.", "emoji": "🦕"}, {"id": "fossil", "en": "fossil", "meaning": "Very old bones or plants turned to stone.", "emoji": "🪨"}, {"id": "skeleton", "en": "skeleton", "meaning": "All the bones of a body.", "emoji": "🦴"}, {"id": "insect", "en": "insect", "meaning": "A small animal with six legs.", "emoji": "🐞"}, {"id": "habitat", "en": "habitat", "meaning": "The place where an animal lives.", "emoji": "🌳"}], "bigQuestion": "Why did dinosaurs disappear?", "bigQuestionOptions": ["The weather changed", "They got sick", "I''m not sure yet"], "challenge": [{"id": "q1", "type": "mc", "prompt": "A fossil is...", "options": ["Very old bones", "A new toy", "A kind of food"], "answer": 0}, {"id": "q2", "type": "tf", "prompt": "An insect has six legs.", "answer": true}, {"id": "q3", "type": "mc", "prompt": "Where does an animal live?", "options": ["Its habitat", "Its fossil", "Its skeleton"], "answer": 0}], "missions": [{"id": "m1", "text": "Find a dinosaur skeleton."}, {"id": "m2", "text": "Find an insect exhibit."}, {"id": "m3", "text": "Find something older than 100 years."}, {"id": "m4", "text": "Take a photo of your favorite exhibit.", "isPhoto": true}], "remember": [{"id": "r1", "type": "mc", "prompt": "What is a fossil?", "options": ["Old bones", "A drink", "A game"], "answer": 0}, {"id": "r2", "type": "tf", "prompt": "Dinosaurs are alive today.", "answer": false}]}');
INSERT INTO programs (id, data) VALUES ('gyeongbokgung', '{"id": "gyeongbokgung", "coverPhoto": "data:image/jpeg;base64,", "title": "Gyeongbokgung Palace", "date": "Sep 20", "dateReached": false, "location": "Seoul", "locationKo": "서울", "level": "A2", "category": "history", "isMuseum": false, "theme": "Walk the grounds where kings once lived and guards once stood watch.", "themeKo": "옛 임금님이 살던 궁궐을 걸어보고, 궁을 지키던 수문장들의 이야기를 들어보았어요.", "emoji": "🏯", "icon": "palace", "roster": ["ella", "mia"], "vocabulary": [{"id": "palace", "en": "palace", "meaning": "A big house for a king or queen.", "emoji": "🏯"}, {"id": "king", "en": "king", "meaning": "A man who rules a country.", "emoji": "👑"}, {"id": "guard", "en": "guard", "meaning": "A person who protects a place.", "emoji": "💂"}, {"id": "gate", "en": "gate", "meaning": "A big door in a wall.", "emoji": "🚪"}, {"id": "throne", "en": "throne", "meaning": "A special chair for a king.", "emoji": "🪑"}], "bigQuestion": "What was it like to live in a palace?", "bigQuestionOptions": ["Comfortable and fancy", "Busy with many guards", "I''m not sure yet"], "challenge": [{"id": "q1", "type": "mc", "prompt": "Who lived in a palace?", "options": ["A king", "A fish", "A robot"], "answer": 0}, {"id": "q2", "type": "tf", "prompt": "A guard protects the palace.", "answer": true}], "missions": [{"id": "m1", "text": "Find the main gate."}, {"id": "m2", "text": "Find a guard''s uniform."}, {"id": "m3", "text": "Find the throne room."}, {"id": "m4", "text": "Take a photo of your favorite exhibit.", "isPhoto": true}], "remember": [{"id": "r1", "type": "mc", "prompt": "A palace is a home for...", "options": ["A king", "A dog", "A teacher"], "answer": 0}]}');
INSERT INTO programs (id, data) VALUES ('warmemorial', '{"id": "warmemorial", "coverPhoto": "data:image/jpeg;base64,", "title": "War Memorial of Korea", "date": "Aug 12", "dateReached": true, "location": "Seoul", "locationKo": "서울", "level": "B1", "category": "history", "isMuseum": true, "theme": "Explore stories of courage and discover why we remember history.", "themeKo": "용기의 이야기를 탐험하며 우리가 왜 역사를 기억해야 하는지 생각해보았어요.", "emoji": "🎖️", "icon": "medal", "roster": ["ella", "noah", "mia"], "vocabulary": [{"id": "soldier", "en": "soldier", "meaning": "A person who serves in the army.", "emoji": "🫡"}, {"id": "memorial", "en": "memorial", "meaning": "Something built to remember people.", "emoji": "🕊️"}, {"id": "peace", "en": "peace", "meaning": "A time without fighting.", "emoji": "☮️"}, {"id": "uniform", "en": "uniform", "meaning": "Special clothes for a job.", "emoji": "👕"}, {"id": "history", "en": "history", "meaning": "Things that happened in the past.", "emoji": "📜"}], "bigQuestion": "Why do we remember history?", "bigQuestionOptions": ["So we don''t forget", "To honor people", "I''m not sure yet"], "challenge": [{"id": "q1", "type": "mc", "prompt": "A soldier serves in the...", "options": ["Army", "Kitchen", "School"], "answer": 0}, {"id": "q2", "type": "tf", "prompt": "A memorial helps us remember.", "answer": true}], "missions": [{"id": "m1", "text": "Find a statue of a soldier."}, {"id": "m2", "text": "Find something from a real war."}, {"id": "m3", "text": "Find the Peace Bell."}, {"id": "m4", "text": "Take a photo of your favorite exhibit.", "isPhoto": true}], "remember": [{"id": "r1", "type": "mc", "prompt": "A memorial is built to...", "options": ["Remember people", "Sell food", "Play games"], "answer": 0}]}');
INSERT INTO programs (id, data) VALUES ('lotte', '{"id": "lotte", "coverPhoto": "data:image/jpeg;base64,", "title": "Lotte Folk Museum", "date": "Jul 18", "dateReached": true, "location": "Seoul", "locationKo": "서울", "level": "A2", "category": "culture", "isMuseum": true, "theme": "Try on tradition and discover how people lived long ago.", "themeKo": "전통 의상을 입어보고 옛날 사람들이 어떻게 살았는지 알아보았어요.", "emoji": "🏺", "icon": "hanbok", "roster": ["ella", "mia"], "vocabulary": [{"id": "tradition", "en": "tradition", "meaning": "Something people have done for a long time.", "emoji": "🎎"}, {"id": "hanbok", "en": "hanbok", "meaning": "Traditional Korean clothing.", "emoji": "👘"}, {"id": "market", "en": "market", "meaning": "A place to buy and sell things.", "emoji": "🏮"}, {"id": "craft", "en": "craft", "meaning": "Something made by hand.", "emoji": "🧵"}, {"id": "village", "en": "village", "meaning": "A small town.", "emoji": "🏘️"}], "bigQuestion": "How did people live long ago?", "bigQuestionOptions": ["Simpler, with handmade things", "Very similar to today", "I''m not sure yet"], "challenge": [{"id": "q1", "type": "mc", "prompt": "A hanbok is a kind of...", "options": ["Clothing", "Food", "Animal"], "answer": 0}, {"id": "q2", "type": "tf", "prompt": "A market is a place to shop.", "answer": true}], "missions": [{"id": "m1", "text": "Find a traditional hanbok."}, {"id": "m2", "text": "Find an old market stall."}, {"id": "m3", "text": "Find something handmade."}, {"id": "m4", "text": "Take a photo of your favorite exhibit.", "isPhoto": true}], "remember": [{"id": "r1", "type": "mc", "prompt": "A hanbok is worn as...", "options": ["Clothing", "A snack", "A toy"], "answer": 0}]}');
