INSERT INTO adventures (id, student_id, program_id, data) VALUES ('ella::warmemorial', 'ella', 'warmemorial', '{"studentId": "ella", "programId": "warmemorial", "beforeCompleted": true, "bigQuestionAnswer": "soldiers protect peace for people", "bigQuestionCustom": true, "challengeScore": {"correct": 2, "total": 2}, "attended": true, "missionsCompleted": [{"missionId": "m1", "done": true, "photo": null}, {"missionId": "m2", "done": true, "photo": null}, {"missionId": "m3", "done": true, "photo": null}, {"missionId": "m4", "done": true, "photo": null}], "afterCompleted": true, "reflection": {"rememberScore": {"correct": 1, "total": 1}, "favoriteText": "the big bell", "favoriteReason": "it was so shiny and had a beautiful sound", "photo": null, "discovery": "soldiers protect peace for everyone", "rating": 5}, "photos": [], "teacherNote": "기념관이 왜 세워졌는지 궁금해하며 좋은 질문을 많이 했어요. 미션을 수행하는 동안 친구들과도 잘 협력했습니다.", "teacherTags": ["Curious", "Team Player"], "feedback": null}');
