INSERT INTO adventures (id, student_id, program_id, data) VALUES ('ella::lotte', 'ella', 'lotte', '{"studentId": "ella", "programId": "lotte", "beforeCompleted": true, "bigQuestionAnswer": "Simpler, with handmade things", "bigQuestionCustom": false, "challengeScore": {"correct": 2, "total": 2}, "attended": true, "missionsCompleted": [{"missionId": "m1", "done": true, "photo": null}, {"missionId": "m2", "done": true, "photo": null}, {"missionId": "m3", "done": true, "photo": null}, {"missionId": "m4", "done": true, "photo": null}], "afterCompleted": true, "reflection": {"rememberScore": {"correct": 1, "total": 1}, "favoriteText": "the hanbok corner", "favoriteReason": "I got to try on colorful traditional clothes", "photo": null, "discovery": "people used markets to trade things long ago", "rating": 5}, "photos": [], "teacherNote": "전통 한복을 입어보는 것을 정말 좋아했고, 옛날 시장에 대해 좋은 질문을 많이 했어요.", "teacherTags": ["Curious", "Great Speaker"], "feedback": {"guideName": "Hannah", "cefrLevel": "B1", "overview": "We had such an exciting field trip exploring Korean history and discovering how people lived and developed throughout different periods! We began our journey all the way back in the Stone Age and Neolithic Age, where we discovered how early people survived through hunting, gathering, and fishing. We learned how their lives gradually changed as they began farming, building homes, making pottery, and creating different tools to help them in their daily lives.\n\nWe then traveled forward in time to explore the Three Kingdoms of Korea — Goguryeo, Baekje, and Silla! We discovered what made each kingdom unique, from Goguryeo''s strong hunting and warrior culture to Baekje''s beautiful craftsmanship and Silla''s impressive gold artifacts and Buddhist influence.\n\nThroughout the trip, we also practiced our English speaking and vocabulary by identifying different objects, describing what we saw, discussing what different tools were made from and used for, and sharing our thoughts and discoveries.", "guideNotes": "Ella was such a lovely student to have on the field trip! She was incredibly interactive and engaged throughout the lesson, always ready to answer questions, share her ideas, and participate in our discussions. She also made friends very easily and brought such a fun and positive energy to the group. Ella has a great sense of humor and often made funny, relevant jokes that kept everyone laughing. Her curiosity, confidence, and cheerful personality made her a wonderful addition to the group.", "language": {"vocabulary": 4, "sentence": 5, "listening": 5, "fluency": 4, "pronunciation": 5}, "personality": {"speaking": "High", "initiation": "High", "listening": "High"}}}');
